import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    for _ in range(T):
        try:
            N = int(next(iterator))
            M = int(next(iterator))
        except StopIteration:
            break

        adj = {}
        for i in range(1, N + 1):
            adj[i] = []

        for _ in range(M):
            u = int(next(iterator))
            v = int(next(iterator))
            w = int(next(iterator))
            adj[u].append((v, w))
            adj[v].append((u, w))

        dist = {i: float('inf') for i in range(1, N + 1)}
        count = {i: 0 for i in range(1, N + 1)}

        dist[1] = 0
        count[1] = 1

        visited = set()

        while True:
            min_node = None
            min_dist = float('inf')

            for i in range(1, N + 1):
                if i not in visited and dist[i] < min_dist:
                    min_dist = dist[i]
                    min_node = i

            if min_node is None or min_node == N:
                break

            visited.add(min_node)

            for neighbor, weight in adj[min_node]:
                if neighbor in visited:
                    continue

                new_dist = dist[min_node] + weight

                if new_dist < dist[neighbor]:
                    dist[neighbor] = new_dist
                    count[neighbor] = count[min_node]
                elif new_dist == dist[neighbor]:
                    count[neighbor] += count[min_node]

        print(count[N])

if __name__ == "__main__":
    solve()
